CREATE FUNCTION guard_agent_run() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF ROW(NEW.id, NEW.workspace_id, NEW.kind, NEW.band, NEW.concurrency_key, NEW.created_at, NEW.deadline)
    IS DISTINCT FROM ROW(OLD.id, OLD.workspace_id, OLD.kind, OLD.band, OLD.concurrency_key, OLD.created_at, OLD.deadline) THEN
  RAISE EXCEPTION 'a run''s identity is immutable' USING ERRCODE = '55000';
 END IF;
 IF OLD.state = 'ENDED' THEN
  RAISE EXCEPTION 'an ended run is final' USING ERRCODE = '55000';
 END IF;
 IF NEW.attempt < OLD.attempt THEN
  RAISE EXCEPTION 'a run''s spent attempts never decrease' USING ERRCODE = '23514';
 END IF;
 IF OLD.state = 'QUEUED' AND NEW.state = 'LEASED' THEN
  IF NEW.lease_epoch <> OLD.lease_epoch + 1 THEN
   RAISE EXCEPTION 'a claim takes the next epoch' USING ERRCODE = '23514';
  END IF;
 ELSIF NEW.lease_epoch <> OLD.lease_epoch THEN
  RAISE EXCEPTION 'only a claim changes the epoch' USING ERRCODE = '23514';
 END IF;
 IF OLD.state = 'LEASED' AND NEW.state = 'LEASED' AND NEW.attempt <> OLD.attempt THEN
  RAISE EXCEPTION 'a renewal spends no attempt' USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER agent_run_transition BEFORE UPDATE ON agent_run FOR EACH ROW EXECUTE FUNCTION guard_agent_run();

ALTER TABLE review_job ADD COLUMN run_id uuid;
UPDATE review_job SET run_id = gen_random_uuid();
INSERT INTO agent_run (id, workspace_id, kind, band, concurrency_key, state, attempt, lease_epoch, leased_until,
                       available_at, stop_reason, created_at, started_at, ended_at)
SELECT j.run_id, j.workspace_id, 'REVIEW',
       CASE WHEN r.origin IN ('SCHEDULE', 'BACKFILL') THEN 'BACKGROUND' ELSE 'BATCH' END,
       'review:' || j.review_id,
       CASE j.status WHEN 'QUEUED' THEN 'QUEUED' WHEN 'RUNNING' THEN 'LEASED' ELSE 'ENDED' END,
       GREATEST(0, j.attempt - j.drain_count - j.room_refusals - j.progressed_attempts),
       CASE WHEN j.status = 'QUEUED' THEN j.attempt ELSE j.attempt + 1 END,
       CASE WHEN j.status = 'RUNNING' THEN now() END,
       j.available_at,
       CASE WHEN j.status IN ('QUEUED', 'RUNNING') THEN NULL
            WHEN j.status = 'CANCELLED' THEN 'CANCELLED' ELSE 'COMPLETED' END,
       j.submitted_at,
       CASE WHEN j.status = 'RUNNING' THEN COALESCE(j.started_at, now()) ELSE j.started_at END,
       CASE WHEN j.status IN ('QUEUED', 'RUNNING') THEN NULL ELSE COALESCE(j.completed_at, now()) END
  FROM review_job j
  LEFT JOIN review r ON r.id = j.review_id AND r.workspace_id = j.workspace_id;
ALTER TABLE review_job ALTER COLUMN run_id SET NOT NULL;
ALTER TABLE review_job ADD CONSTRAINT uk_review_job_run UNIQUE (run_id, workspace_id);
ALTER TABLE review_job ADD CONSTRAINT sfk_review_job_run FOREIGN KEY (run_id, workspace_id)
    REFERENCES agent_run (id, workspace_id);
DROP INDEX IF EXISTS idx_review_job_queue;
DROP INDEX IF EXISTS ix_review_job_running_lease;
ALTER TABLE review_job DROP CONSTRAINT IF EXISTS ck_review_job_attempt;
ALTER TABLE review_job DROP COLUMN lease_id, DROP COLUMN leased_until, DROP COLUMN attempt,
    DROP COLUMN drain_count, DROP COLUMN room_refusals, DROP COLUMN progressed_attempts, DROP COLUMN available_at;

CREATE FUNCTION enforce_review_job_run() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
 job_status varchar;
 run_state varchar;
BEGIN
 FOR job_status, run_state IN
  SELECT j.status, r.state FROM review_job j JOIN agent_run r ON r.id = j.run_id
   WHERE (TG_TABLE_NAME = 'review_job' AND j.id = NEW.id) OR (TG_TABLE_NAME = 'agent_run' AND j.run_id = NEW.id)
 LOOP
  IF NOT ((job_status = 'QUEUED' AND run_state = 'QUEUED')
       OR (job_status = 'RUNNING' AND run_state = 'LEASED')
       OR (job_status NOT IN ('QUEUED', 'RUNNING') AND run_state = 'ENDED')) THEN
   RAISE EXCEPTION 'a review job that is % needs a run that agrees, not one that is %', job_status, run_state
    USING ERRCODE = '23514';
  END IF;
 END LOOP;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER review_job_run_agrees AFTER INSERT OR UPDATE OF status, run_id ON review_job
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION enforce_review_job_run();
CREATE CONSTRAINT TRIGGER agent_run_review_agrees AFTER UPDATE OF state ON agent_run
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN (NEW.kind = 'REVIEW') EXECUTE FUNCTION enforce_review_job_run();
